import java.util.ArrayList;
import java.util.List;
import java.util.stream.Gatherer;
import java.util.stream.Stream;

public class GathererDemo {
    public static <T> Gatherer<T, ?, List<T>> windowFixed(int windowSize) {
        if (windowSize <= 0) throw new IllegalArgumentException("Window size must be positive");

        return Gatherer.ofSequential(
            ArrayList::new,
            (state, element, downstream) -> {
                state.add(element);
                if (state.size() == windowSize) {
                    List<T> window = List.copyOf(state);
                    state.clear();
                    return downstream.push(window);
                }
                return !downstream.isStopped();
            },
            (state, downstream) -> {
                if (!state.isEmpty()) {
                    downstream.push(List.copyOf(state));
                }
            }
        );
    }

    public static void main(String[] args) {
        List<Integer> numbers = List.of(1, 2, 3, 4, 5, 6, 7);

        List<List<Integer>> windows = numbers.stream()
            .gather(windowFixed(3))
            .toList();

        System.out.println(windows); // [[1, 2, 3], [4, 5, 6], [7]]
    }
}
